import { generateText } from "ai";
import { z } from "zod";
import { transformOperationKey } from "@/lib/billing/operation-key";
import { commitReservation, releaseReservation, reserveCredits } from "@/lib/billing/server";
import { BillingDomainError } from "@/lib/billing/types";
import { authenticateDeveloperRequest } from "@/lib/developer-api";
import { countWords, MAX_REWRITE_WORDS } from "@/lib/product-contract";
import { planSanitizationJob, SanitizationContractError } from "@/lib/sanitization";
import { ApiRequestError, apiError, apiOk, parseJson, requestContext, retryAfter } from "@/lib/server/api";
import { logEvent, requestSubjectKey } from "@/lib/server/observability";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";
import {
  chunkProtectedText,
  prepareProtectedText,
  TRANSFORM_INTENSITIES,
  TRANSFORM_MODES,
  TRANSFORM_PURPOSES,
  TRANSFORM_SYSTEM,
  transformPrompt,
  unavailableTextWatermarkVerifier,
  validateTransformedDraft,
} from "@/lib/transform";
import type { TransformIntensity, TransformMode, TransformPurpose, TransformResult } from "@/lib/transform";

export const runtime = "nodejs";
const DEFAULT_MODEL = "mistral/mistral-medium-3.5";
const MAX_ATTEMPTS = 2;
const bodySchema = z.object({
  operationId: z.string().uuid(),
  text: z.string().trim().min(20).max(250_000),
  mode: z.enum(TRANSFORM_MODES),
  intensity: z.enum(TRANSFORM_INTENSITIES).default("balanced"),
  purpose: z.enum(TRANSFORM_PURPOSES).default("general"),
});

function wordBucket(words: number) {
  if (words <= 250) return "<=250";
  if (words <= 1_000) return "251-1000";
  if (words <= 4_000) return "1001-4000";
  return "4001-8000";
}

async function generateAttempt(
  protectedText: string,
  mode: TransformMode,
  intensity: TransformIntensity,
  purpose: TransformPurpose,
  model: string,
  retryFeedback?: string,
) {
  const outputs: string[] = [];
  for (const chunk of chunkProtectedText(protectedText)) {
    const { text } = await generateText({
      model,
      system: TRANSFORM_SYSTEM,
      prompt: transformPrompt(chunk, mode, intensity, purpose, retryFeedback),
      temperature: intensity === "light" ? 0.2 : intensity === "strong" ? 0.4 : 0.3,
    });
    outputs.push(text.trim());
  }
  return outputs.join("\n\n");
}

function billingError(context: ReturnType<typeof requestContext>, error: BillingDomainError) {
  if (error.code === "insufficient_credits") return apiError(context, error.code, "Not enough credits are available for this edit.", 402);
  if (error.code === "rate_limited" || error.code === "daily_credit_limit") {
    return apiError(context, error.code, error.code === "rate_limited" ? "Too many editing requests were started recently." : "The daily editing-credit safety limit has been reached.", 429, retryAfter(60));
  }
  if (error.code === "operation_conflict") return apiError(context, error.code, "This edit operation has already been used.", 409);
  return apiError(context, "billing_unavailable", "Billing is not available.", 503);
}

export async function POST(request: Request) {
  const context = requestContext(request, "/api/v1/transform");
  let identity;
  try { identity = await authenticateDeveloperRequest(request); }
  catch { return apiError(context, "developer_api_unavailable", "Developer API authentication is unavailable.", 503); }
  if (!identity) return apiError(context, "invalid_api_key", "A valid Bearer API key is required.", 401, { "www-authenticate": "Bearer" });

  const subject = requestSubjectKey(request, identity.keyId);
  const burst = consumeRateLimit("developer-transform", subject, configuredLimit("RATE_LIMIT_DEVELOPER_TRANSFORM_PER_MINUTE", 12), 60_000);
  if (!burst.allowed) return apiError(context, "rate_limited", "Developer transform rate limit exceeded.", 429, retryAfter(burst.retryAfterSeconds));

  let parsed: z.infer<typeof bodySchema>;
  try { parsed = await parseJson(request, bodySchema, 300_000); }
  catch (error) {
    return error instanceof ApiRequestError ? apiError(context, error.code, error.message, error.status) : apiError(context, "invalid_request", "Request is invalid.", 400);
  }

  let job;
  try { job = planSanitizationJob({ kind: "text", intent: "rewrite", text: parsed.text }); }
  catch (error) {
    if (error instanceof SanitizationContractError && error.code === "rewrite_too_large") {
      return apiError(context, "rewrite_too_large", `Semantic editing accepts at most ${MAX_REWRITE_WORDS.toLocaleString("en-US")} words per operation. Split larger documents into parts.`, 413);
    }
    return apiError(context, "invalid_request", "The rewrite job does not satisfy the product contract.", 400);
  }

  const cost = job.credits;
  const sourceWords = countWords(parsed.text);
  logEvent("developer_transform_request", {
    requestId: context.requestId,
    developerKeyHash: subject,
    operationId: parsed.operationId,
    sourceWordBucket: wordBucket(sourceWords),
    credits: cost,
    mode: parsed.mode,
    intensity: parsed.intensity,
    purpose: parsed.purpose,
  });

  let reservationId: string;
  try {
    const reservation = await reserveCredits(identity.userId, transformOperationKey(parsed.operationId), cost);
    reservationId = reservation.reservationId;
    if (!reservation.created || reservation.status !== "reserved") return apiError(context, "operation_conflict", "This edit operation is already in progress or complete.", 409);
  } catch (error) {
    if (error instanceof BillingDomainError) return billingError(context, error);
    return apiError(context, "billing_unavailable", "Billing is not available.", 503);
  }

  const prepared = prepareProtectedText(parsed.text);
  const model = process.env.TRANSFORM_MODEL ?? DEFAULT_MODEL;
  let retryFeedback: string | undefined;
  try {
    for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt += 1) {
      const draft = await generateAttempt(prepared.protectedText, parsed.mode, parsed.intensity, parsed.purpose, model, retryFeedback);
      const validation = validateTransformedDraft(prepared, draft, parsed.mode);
      if (validation.ok && validation.restoredText) {
        const balance = await commitReservation(identity.userId, reservationId);
        const watermark = await unavailableTextWatermarkVerifier.verify(validation.restoredText);
        const result: TransformResult = {
          version: "semantic-transform-v2",
          text: validation.restoredText,
          mode: parsed.mode,
          intensity: parsed.intensity,
          purpose: parsed.purpose,
          model,
          attempts: attempt,
          metrics: validation.metrics,
          receipt: {
            sourceWords: validation.metrics.sourceWords,
            outputWords: validation.metrics.outputWords,
            retainedPercent: validation.metrics.retainedPercent,
            wordingReplacedPercent: validation.metrics.wordingReplacedPercent,
            longestUnprotectedSharedWordRun: validation.metrics.unprotectedLongestSharedWordRun,
            protectedSpanCount: validation.metrics.protectedTotal,
            checks: validation.checks,
            model,
            attempts: attempt,
            creditsCharged: cost,
          },
          watermark,
          warnings: validation.warnings,
          billing: { operationId: parsed.operationId, reservationId, creditsCharged: cost, balanceAfter: balance.available },
        };
        logEvent("developer_transform_success", {
          requestId: context.requestId,
          developerKeyHash: subject,
          operationId: parsed.operationId,
          model,
          attempts: attempt,
          credits: cost,
          intensity: parsed.intensity,
          purpose: parsed.purpose,
          latencyMs: Date.now() - context.startedAt,
        });
        return apiOk(context, result as unknown as Record<string, unknown>);
      }
      retryFeedback = validation.errors.map((item) => `- ${item}`).join("\n");
    }
    await releaseReservation(identity.userId, reservationId, "validation_failed");
    return apiError(context, "validation_failed", "The edit did not pass factual-preservation checks. The credit hold was released.", 422);
  } catch {
    try { await releaseReservation(identity.userId, reservationId, "generation_failed"); } catch {}
    return apiError(context, "model_unavailable", "The editing service is temporarily unavailable. The credit hold was released or will expire automatically.", 503);
  }
}

-- Phase 9: developer API keys and machine-to-machine access.
-- Raw API secrets are never persisted; only SHA-256 hashes and display prefixes are stored.

create table if not exists ops.developer_api_keys (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  name text not null check (char_length(btrim(name)) between 1 and 80),
  key_prefix text not null check (key_prefix ~ '^pc_sk_[A-Za-z0-9_-]{4,24}$'),
  key_hash text not null unique check (key_hash ~ '^[0-9a-f]{64}$'),
  created_at timestamptz not null default now(),
  last_used_at timestamptz,
  revoked_at timestamptz
);

create index if not exists developer_api_keys_user_active_idx
  on ops.developer_api_keys(user_id, created_at desc)
  where revoked_at is null;

alter table ops.developer_api_keys enable row level security;
revoke all on table ops.developer_api_keys from public, anon, authenticated;
grant select, insert, update, delete on table ops.developer_api_keys to service_role;

create or replace function public.developer_api_key_create(
  p_user_id uuid,
  p_name text,
  p_prefix text,
  p_hash text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key ops.developer_api_keys%rowtype;
  v_name text := btrim(coalesce(p_name, ''));
begin
  if p_user_id is null
     or not exists (
       select 1
       from auth.users u
       where u.id = p_user_id
         and coalesce(u.is_anonymous, false) = false
         and u.email_confirmed_at is not null
     ) then
    raise exception 'developer_api_requires_verified_account';
  end if;

  if char_length(v_name) < 1 or char_length(v_name) > 80 then
    raise exception 'developer_api_key_name_invalid';
  end if;
  if p_prefix !~ '^pc_sk_[A-Za-z0-9_-]{4,24}$' or p_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'developer_api_key_material_invalid';
  end if;
  if (select count(*) from ops.developer_api_keys k where k.user_id = p_user_id and k.revoked_at is null) >= 10 then
    raise exception 'developer_api_key_limit';
  end if;

  insert into ops.developer_api_keys(user_id, name, key_prefix, key_hash)
  values (p_user_id, v_name, p_prefix, p_hash)
  returning * into v_key;

  return jsonb_build_object(
    'id', v_key.id,
    'name', v_key.name,
    'prefix', v_key.key_prefix,
    'createdAt', v_key.created_at
  );
end;
$$;

create or replace function public.developer_api_key_list(p_user_id uuid)
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', k.id,
        'name', k.name,
        'prefix', k.key_prefix,
        'createdAt', k.created_at,
        'lastUsedAt', k.last_used_at,
        'revokedAt', k.revoked_at
      ) order by k.created_at desc
    ),
    '[]'::jsonb
  )
  from ops.developer_api_keys k
  where k.user_id = p_user_id;
$$;

create or replace function public.developer_api_key_revoke(p_user_id uuid, p_key_id uuid)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_changed integer;
begin
  update ops.developer_api_keys
  set revoked_at = coalesce(revoked_at, now())
  where id = p_key_id and user_id = p_user_id and revoked_at is null;
  get diagnostics v_changed = row_count;
  return v_changed = 1;
end;
$$;

create or replace function public.developer_api_key_resolve(p_hash text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_key ops.developer_api_keys%rowtype;
begin
  if p_hash !~ '^[0-9a-f]{64}$' then
    return null;
  end if;

  select * into v_key
  from ops.developer_api_keys k
  where k.key_hash = p_hash and k.revoked_at is null;

  if not found then
    return null;
  end if;

  if not exists (
    select 1
    from auth.users u
    where u.id = v_key.user_id
      and coalesce(u.is_anonymous, false) = false
      and u.email_confirmed_at is not null
  ) then
    return null;
  end if;

  if v_key.last_used_at is null or v_key.last_used_at < now() - interval '5 minutes' then
    update ops.developer_api_keys set last_used_at = now() where id = v_key.id;
  end if;

  return jsonb_build_object(
    'keyId', v_key.id,
    'userId', v_key.user_id,
    'prefix', v_key.key_prefix
  );
end;
$$;

create or replace function public.developer_phase9_status()
returns jsonb
language sql
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'ready',
      to_regclass('ops.developer_api_keys') is not null
      and to_regprocedure('public.developer_api_key_create(uuid,text,text,text)') is not null
      and to_regprocedure('public.developer_api_key_list(uuid)') is not null
      and to_regprocedure('public.developer_api_key_revoke(uuid,uuid)') is not null
      and to_regprocedure('public.developer_api_key_resolve(text)') is not null,
    'schemaVersion', '20260914153000',
    'hashedSecretsOnly', true,
    'verifiedAccountsOnly', true,
    'revocationSupported', true
  );
$$;

revoke all on function public.developer_api_key_create(uuid,text,text,text) from public, anon, authenticated;
revoke all on function public.developer_api_key_list(uuid) from public, anon, authenticated;
revoke all on function public.developer_api_key_revoke(uuid,uuid) from public, anon, authenticated;
revoke all on function public.developer_api_key_resolve(text) from public, anon, authenticated;
revoke all on function public.developer_phase9_status() from public, anon, authenticated;

grant execute on function public.developer_api_key_create(uuid,text,text,text) to service_role;
grant execute on function public.developer_api_key_list(uuid) to service_role;
grant execute on function public.developer_api_key_revoke(uuid,uuid) to service_role;
grant execute on function public.developer_api_key_resolve(text) to service_role;
grant execute on function public.developer_phase9_status() to service_role;

# Developer API

Phase 9 adds server-to-server automation without weakening the existing privacy, billing, or provenance contracts.

## Authentication

Developer access uses Bearer keys created from the verified Account page. Keys begin with `pc_sk_`.

- raw secrets are returned exactly once at creation time;
- only a SHA-256 digest and short display prefix are stored;
- anonymous or unverified accounts cannot create keys;
- up to 10 active keys are allowed per account;
- revocation is immediate;
- deleting the Supabase user cascades developer keys;
- never expose a key in browser code, public repositories, client-side environment variables, analytics, or logs.

```http
Authorization: Bearer pc_sk_...
```

## `POST /api/v1/scan`

Free deterministic Unicode inspection and optional sanitation. This route does not spend credits.

```json
{
  "text": "Text to inspect",
  "sanitize": "none"
}
```

`sanitize` is one of `none`, `conservative`, or `aggressive`.

The response contains the same deterministic scan receipt and optional sanitation evidence used by the product UI. The route is rate limited per API key and does not persist submitted text.

## `GET /api/v1/usage`

Returns the authoritative credit balance for the account attached to the API key.

```json
{
  "balance": {
    "settled": 25,
    "held": 0,
    "available": 25
  },
  "key": {
    "prefix": "pc_sk_..."
  }
}
```

## `POST /api/v1/transform`

Runs the same protected-span semantic transformation contract as the browser workbench, using the API-key owner's authoritative credit account.

```json
{
  "operationId": "8e1d8274-f4e9-44bf-98fb-2aa2b8bd2c4a",
  "text": "Text long enough to satisfy the transform contract.",
  "mode": "natural",
  "purpose": "work",
  "intensity": "balanced"
}
```

`mode` is one of `parity`, `natural`, `clarity`, `concise`, or `formal`. `purpose` is one of `general`, `email`, `work`, `academic`, or `social`. `intensity` is one of `light`, `balanced`, or `strong`. Purpose and intensity default to `general` and `balanced` for backwards compatibility.

Important guarantees:

- the 8,000-word product limit still applies;
- credit cost is calculated by the same sanitization contract;
- reserve → generate → deterministic validation → commit is preserved;
- failed generation or validation releases the hold;
- operation IDs are idempotency boundaries shared with the existing transform surface;
- protected quotations, references, URLs, emails, dates, numerics and detected proper names retain the same validation rules;
- the API does not claim detector-proof or watermark-removal verification.

A developer key replaces the interactive Turnstile challenge for machine-to-machine requests, but API-key rate limits and the database-authoritative billing limits still apply.

## CLI

Node 22+ can use the committed zero-dependency CLI:

```bash
export PROVENANCE_API_KEY='pc_sk_...'
export PROVENANCE_API_URL='https://your-host.example'

npm run provenance:cli -- usage
npm run provenance:cli -- scan ./sample.txt conservative
npm run provenance:cli -- transform ./sample.txt natural work balanced
cat ./sample.txt | npm run provenance:cli -- scan - none
```

The CLI never prints the API key. Transform output and receipts are printed to stdout because they are the requested user result.

## Error contract

API errors use the standard Provenance Cleaner shape:

```json
{
  "error": {
    "code": "invalid_api_key",
    "message": "A valid Bearer API key is required.",
    "requestId": "..."
  }
}
```

Common status codes:

- `400` invalid request;
- `401` invalid or revoked API key;
- `402` insufficient credits;
- `409` duplicate operation ID or API-key limit;
- `413` transform exceeds the product limit;
- `422` transform failed deterministic validation;
- `429` rate or spend limit;
- `503` dependent service unavailable.

## Database boundary

The private `ops.developer_api_keys` table is RLS-enabled and inaccessible to `anon` and `authenticated`. Management and resolution RPCs are executable only by `service_role`. `developer_phase9_status()` exposes only non-secret readiness evidence.


## Chrome safe editor

The repository includes a Manifest V3 extension in `extension/chrome`. It uses the same `/api/v1/transform` contract, supports mode/purpose/intensity, can replace selected text in editable fields, and keeps one in-memory undo record. The extension stores the developer API key and preferences only; selected source text and generated output are not written to extension storage.

"use client";

import { useCallback, useState } from "react";
import { useRouter } from "next/navigation";
import { CREDIT_PACKS, type CreditPackId } from "@/lib/billing/catalog";
import { TurnstileWidget } from "@/components/turnstile-widget";

function messageFrom(payload: unknown, fallback: string) {
  if (payload && typeof payload === "object") {
    const error = (payload as { error?: unknown }).error;
    if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
      return (error as { message: string }).message;
    }
    if (typeof error === "string") return error;
  }
  return fallback;
}

export function CreditPackGrid({ compact = false }: { compact?: boolean }) {
  const router = useRouter();
  const [challengeToken, setChallengeToken] = useState<string | null>(null);
  const [resetKey, setResetKey] = useState(0);
  const [busyPack, setBusyPack] = useState<CreditPackId | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const onToken = useCallback((token: string | null) => setChallengeToken(token), []);

  async function buy(packId: CreditPackId) {
    if (!challengeToken) return;
    setBusyPack(packId);
    setMessage(null);
    try {
      const response = await fetch("/api/billing/checkout", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ packId, challengeToken }),
      });
      const payload = await response.json();
      if (response.status === 401) {
        router.push("/auth");
        return;
      }
      if (!response.ok || typeof payload?.url !== "string") {
        throw new Error(messageFrom(payload, "Checkout is not available."));
      }
      window.location.assign(payload.url);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Checkout is not available.");
      setChallengeToken(null);
      setResetKey(value => value + 1);
      setBusyPack(null);
    }
  }

  if (compact) {
    return <div className="account-topup">
      <div className="account-topup-head">
        <div><p className="eyebrow">One-time top up</p><h2>Add processing allowance without a subscription.</h2></div>
        <span className="pill">Stripe TEST</span>
      </div>
      <div className="account-topup-actions">
        {Object.values(CREDIT_PACKS).map(pack => <button
          key={pack.id}
          className="ghost"
          type="button"
          disabled={!challengeToken || busyPack !== null}
          onClick={() => void buy(pack.id)}
        >
          {busyPack === pack.id ? "Opening Stripe…" : `${pack.credits} units · ${pack.priceUsd.toFixed(2)}`}
        </button>)}
      </div>
      <TurnstileWidget action="account" onToken={onToken} resetKey={resetKey} />
      {message && <p className="notice-card" role="status">{message}</p>}
    </div>;
  }

  return <div>
    <div className="credit-pack-grid">
