#!/usr/bin/env node

import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, unlinkSync, writeFileSync } from "node:fs";
import { checkSourceManifest, SOURCE_MANIFEST_PATH } from "./source-manifest.mjs";

const TRANSPORT_PATHS = Array.from(
  { length: 14 },
  (_, index) => `release/oauth-bundle-${index + 1}.json`,
);
const DIRECT_SOURCE_PATHS = new Set([
  "package.json",
  "package-lock.json",
  "release/oauth-unpack.mjs",
  "vercel.json",
]);
const TRANSPORT_PATH_SET = new Set(TRANSPORT_PATHS);

function gitBlobSha(content) {
  const body = Buffer.from(content, "utf8");
  return createHash("sha1")
    .update(`blob ${body.length}\0`, "utf8")
    .update(body)
    .digest("hex");
}

function trackedEntries() {
  const output = execFileSync("git", ["ls-files", "-s"], { encoding: "utf8" });
  return output
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const tab = line.indexOf("\t");
      if (tab < 0) throw new Error(`Invalid git ls-files entry: ${line}`);
      const [mode, sha, stage] = line.slice(0, tab).trim().split(/\s+/u);
      const path = line.slice(tab + 1);
      if (!mode || !sha || stage !== "0") {
        throw new Error(`Unsupported git index entry: ${line}`);
      }
      return { path, sha };
    })
    .sort((a, b) => a.path.localeCompare(b.path));
}

for (const path of TRANSPORT_PATHS) {
  if (existsSync(path)) unlinkSync(path);
}

const certification = checkSourceManifest();
const entries = trackedEntries();

for (const { path } of entries) {
  if (TRANSPORT_PATH_SET.has(path)) {
    throw new Error(`OAuth transport files must never be tracked in the certified source tree: ${path}`);
  }
}

const sourceFiles = [];
for (const { path, sha } of entries) {
  if (path === SOURCE_MANIFEST_PATH || DIRECT_SOURCE_PATHS.has(path)) continue;
  const data = readFileSync(path, "utf8");
  const actualSha = gitBlobSha(data);
  if (actualSha !== sha) {
    throw new Error(
      `OAuth packer requires UTF-8 source whose Git blob matches the index: ${path}`,
    );
  }
  sourceFiles.push({
    path,
    blobSha: sha,
    data,
    bytes: Buffer.byteLength(data, "utf8"),
  });
}

const bootstrap = [];
for (const path of DIRECT_SOURCE_PATHS) {
  const entry = entries.find((item) => item.path === path);
  if (!entry) throw new Error(`OAuth packer missing required direct source file: ${path}`);
  const data = readFileSync(path, "utf8");
  if (gitBlobSha(data) !== entry.sha) {
    throw new Error(`OAuth packer direct file differs from the Git index: ${path}`);
  }
  bootstrap.push({
    path,
    blobSha: entry.sha,
    ...(path === "vercel.json" ? { data } : {}),
  });
}

const bins = Array.from({ length: TRANSPORT_PATHS.length }, () => ({
  bytes: 0,
  files: [],
}));

for (const file of [...sourceFiles].sort((a, b) => b.bytes - a.bytes)) {
  bins.sort((a, b) => a.bytes - b.bytes);
  bins[0].files.push(file);
  bins[0].bytes += file.bytes;
}

bins.forEach((bin, index) => {
  const payload = {
    schemaVersion: 3,
    sourceHash: certification.sourceHash,
    bootstrap,
    files: bin.files.map(({ path, blobSha, data }) => ({ path, blobSha, data })),
  };
  writeFileSync(TRANSPORT_PATHS[index], JSON.stringify(payload), "utf8");
});

const totalBytes = bins.reduce((sum, bin) => sum + bin.bytes, 0);
console.log(
  `OAuth transport: packed ${sourceFiles.length} tracked files (${totalBytes} UTF-8 bytes) into ${TRANSPORT_PATHS.length} certified parts for ${certification.releaseId}.`,
);

"use client";

import { useCallback, useState } from "react";
import { useRouter } from "next/navigation";
import { SUBSCRIPTION_PLANS, type SubscriptionPlanId } from "@/lib/billing/subscriptions";
import { TurnstileWidget } from "@/components/turnstile-widget";

function messageFrom(payload: unknown, fallback: string) {
  if (payload && typeof payload === "object") {
    const error = (payload as { error?: unknown }).error;
    if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
      return (error as { message: string }).message;
    }
  }
  return fallback;
}

export function SubscriptionPlanGrid() {
  const router = useRouter();
  const [challengeToken, setChallengeToken] = useState<string | null>(null);
  const [resetKey, setResetKey] = useState(0);
  const [busyPlan, setBusyPlan] = useState<SubscriptionPlanId | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const onToken = useCallback((token: string | null) => setChallengeToken(token), []);

  async function subscribe(planId: SubscriptionPlanId) {
    if (!challengeToken) return;
    setBusyPlan(planId);
    setMessage(null);
    try {
      const response = await fetch("/api/billing/subscription-checkout", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ planId, challengeToken }),
      });
      const payload = await response.json();
      if (response.status === 401) {
        router.push("/auth");
        return;
      }
      if (!response.ok || typeof payload?.url !== "string") {
        throw new Error(messageFrom(payload, "Monthly checkout is not available."));
      }
      window.location.assign(payload.url);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Monthly checkout is not available.");
      setChallengeToken(null);
      setResetKey(value => value + 1);
      setBusyPlan(null);
    }
  }

  return <div>
    <div className="credit-pack-grid">
      {Object.values(SUBSCRIPTION_PLANS).map(plan => <article className="credit-pack-card" key={plan.id}>
        <span className="mono-label">MONTHLY PLAN</span>
        <strong>{plan.credits}<small> units / mo</small></strong>
        <h2>{plan.label}</h2>
        <p>{`${(plan.monthlyCents / 100).toFixed(2)} / month · up to ~${plan.credits.toLocaleString()}K words of text processing · TEST mode`}</p>
        <div className="pack-unit">One-time processing packs remain available.</div>
        <button className="primary" type="button" disabled={!challengeToken || busyPlan !== null} onClick={() => void subscribe(plan.id)}>
          {busyPlan === plan.id ? "Opening Stripe…" : `Subscribe to ${plan.label}`}
        </button>
      </article>)}
    </div>
    <TurnstileWidget action="account" onToken={onToken} resetKey={resetKey} />
    {message && <p className="notice-card" role="status">{message}</p>}
  </div>;
}

