interface Bucket { count: number; resetAt: number; }
interface RateResult { allowed: boolean; remaining: number; retryAfterSeconds: number; }
declare global { var __provenanceRateBuckets: Map<string, Bucket> | undefined; }
const buckets = globalThis.__provenanceRateBuckets ??= new Map<string, Bucket>();
const MAX_BUCKETS = 5_000;

function makeRoom(now: number) {
  if (buckets.size < MAX_BUCKETS) return;
  for (const [key, bucket] of buckets) if (bucket.resetAt <= now) buckets.delete(key);
  if (buckets.size < MAX_BUCKETS) return;
  let oldestKey: string | undefined;
  let oldestReset = Number.POSITIVE_INFINITY;
  for (const [key, bucket] of buckets) {
    if (bucket.resetAt < oldestReset) { oldestReset = bucket.resetAt; oldestKey = key; }
  }
  if (oldestKey) buckets.delete(oldestKey);
}

export function consumeRateLimit(namespace: string, subject: string, limit: number, windowMs: number, now = Date.now()): RateResult {
  if (limit <= 0) return { allowed: true, remaining: Number.MAX_SAFE_INTEGER, retryAfterSeconds: 0 };
  const key = `${namespace}:${subject}`;
  const current = buckets.get(key);
  if (!current || current.resetAt <= now) {
    if (!current) makeRoom(now);
    buckets.set(key, { count: 1, resetAt: now + windowMs });
    return { allowed: true, remaining: Math.max(0, limit - 1), retryAfterSeconds: 0 };
  }
  if (current.count >= limit) return { allowed: false, remaining: 0, retryAfterSeconds: Math.max(1, Math.ceil((current.resetAt - now) / 1000)) };
  current.count += 1;
  return { allowed: true, remaining: Math.max(0, limit - current.count), retryAfterSeconds: 0 };
}
export function configuredLimit(name: string, fallback: number) { const value = Number.parseInt(process.env[name] ?? "", 10); return Number.isFinite(value) && value >= 0 ? value : fallback; }
export function resetRateLimitsForTests() { buckets.clear(); }
export function rateLimitBucketCountForTests() { return buckets.size; }

export type CostSource = "ACTUAL" | "ESTIMATED" | "MANUAL" | "CONFIRMED_ZERO";
export type ProviderCost = { provider: string; amountMicros: number; source: CostSource; units?: number };

export function microsToCents(micros: number) { return Math.round(micros / 10_000); }
export function sumMicros(costs: ReadonlyArray<ProviderCost>) { return costs.reduce((sum, cost) => sum + Math.max(0, Math.trunc(cost.amountMicros)), 0); }
export function budgetStatus(spendMicros: number, budgetMicros: number, warningPercent = 75, criticalPercent = 90) {
  if (budgetMicros <= 0) return "pending" as const;
  const percent = (spendMicros * 100) / budgetMicros;
  if (percent >= 100) return "critical" as const;
  if (percent >= criticalPercent) return "critical" as const;
  if (percent >= warningPercent) return "warning" as const;
  return "healthy" as const;
}
export function projectedMonthEndMicros(monthToDateMicros: number, elapsedDays: number, daysInMonth: number) {
  if (elapsedDays <= 0 || daysInMonth <= 0) return 0;
  return Math.round((monthToDateMicros / elapsedDays) * daysInMonth);
}
export function contributionMargin(netRevenueCents: number, variableCostMicros: number) {
  const costCents = microsToCents(variableCostMicros);
  const contributionCents = netRevenueCents - costCents;
  return { contributionCents, percent: netRevenueCents > 0 ? Math.round((contributionCents * 10_000) / netRevenueCents) / 100 : null };
}
export function costCoverage(providers: ReadonlyArray<{ source: CostSource | null }>) {
  if (providers.length === 0) return 0;
  return Math.round((providers.filter((provider) => provider.source !== null).length / providers.length) * 100);
}

import { getCreditBalance } from "@/lib/billing/server";
import { authenticateDeveloperRequest } from "@/lib/developer-api";
import { apiError, apiOk, requestContext, retryAfter } from "@/lib/server/api";
import { requestSubjectKey } from "@/lib/server/observability";
import { configuredLimit, consumeRateLimit } from "@/lib/server/rate-limit";

export async function GET(request: Request) {
  const context = requestContext(request, "/api/v1/usage");
  let identity;
  try { identity = await authenticateDeveloperRequest(request); }
  catch { return apiError(context, "developer_api_unavailable", "Developer API authentication is unavailable.", 503); }
  if (!identity) return apiError(context, "invalid_api_key", "A valid Bearer API key is required.", 401, { "www-authenticate": "Bearer" });

  const subject = requestSubjectKey(request, identity.keyId);
  const limit = consumeRateLimit("developer-usage", subject, configuredLimit("RATE_LIMIT_DEVELOPER_USAGE_PER_MINUTE", 30), 60_000);
  if (!limit.allowed) return apiError(context, "rate_limited", "Developer usage rate limit exceeded.", 429, retryAfter(limit.retryAfterSeconds));

  try {
    const balance = await getCreditBalance(identity.userId);
    return apiOk(context, { balance, key: { prefix: identity.prefix } }, 200, { "cache-control": "no-store" });
  } catch {
    return apiError(context, "billing_unavailable", "Usage balance is temporarily unavailable.", 503);
  }
}

import { describe, expect, it } from "vitest";
import { sanitizeText, scanText } from "../src/lib/provenance/unicode";

describe("Unicode provenance scanner", () => {
  it("finds a zero-width space and marks it safe to remove", () => {
    const receipt = scanText("hello\u200Bworld", "2026-08-31T00:00:00.000Z");
    expect(receipt.summary.total).toBe(1);
    expect(receipt.summary.safeToRemove).toBe(1);
    expect(receipt.findings[0].codePoint).toBe("U+200B");
  });

  it("preserves ZWJ in conservative mode", () => {
    const text = "family 👩\u200D👩\u200D👧\u200D👦";
    const result = sanitizeText(text, "conservative");
    expect(result.output).toBe(text);
    expect(result.preservedForReview.length).toBe(3);
  });

  it("flags bidi controls for review", () => {
    const receipt = scanText("abc\u202Edef");
    expect(receipt.summary.reviewRequired).toBe(1);
    expect(receipt.findings[0].category).toBe("bidi_control");
  });

  it("removes safe hidden characters without changing visible text", () => {
    const result = sanitizeText("a\u200Bb\uFEFFc", "conservative");
    expect(result.output).toBe("abc");
    expect(result.removed).toHaveLength(2);
  });
});

